const menu=document.querySelector('.menu');const nav=document.querySelector('#navigation');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
const sections=[...document.querySelectorAll('main>section')];const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){nav.querySelectorAll('a').forEach(a=>{const active=a.hash==='#'+e.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}})},{rootMargin:'-15% 0px -60% 0px',threshold:0});sections.forEach(s=>observer.observe(s));
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('.project').forEach(p=>p.hidden=button.dataset.filter!=='all'&&p.dataset.category!==button.dataset.filter)}));
const work={business:{tag:'MONIEPOINT INC. / SEPTEMBER 2024 — SEPTEMBER 2025',title:'Business performance, made visible.',body:'<p>As a Performance Analyst at Moniepoint, I worked with regional management and stakeholders to define business performance metrics and make operational data easier to act on.</p><h3>The work</h3><ul><li>Defined and monitored KPIs with business stakeholders.</li><li>Developed performance measurement frameworks using quantitative and qualitative data.</li><li>Designed interactive dashboards for daily performance tracking.</li><li>Analyzed trends and tested hypotheses about services and products.</li><li>Produced recurring reports with recommendations for management.</li></ul><h3>The approach</h3><p>Start with the business question, agree on the metric, examine the evidence, and communicate findings in a form decision-makers can use.</p><p>This is a summary of professional experience. The portfolio illustration uses no company data and is not an actual dashboard screenshot.</p>'},geo:{tag:'ACADEMIC PROJECT / RUHR UNIVERSITY BOCHUM',title:'Reading a landscape through its rivers.',body:'<p>A computational geomorphology study of the Sorbas region in southeastern Spain, using the Copernicus GLO-30 elevation model and TopoToolbox in MATLAB.</p><h3>From terrain to evidence</h3><p>The DEM was reprojected to UTM zone 30N at 30 m resolution. Channels were extracted above a 1 km² contributing-area threshold, then filtered to select the largest remaining connected network.</p><ul><li>Calculated normalized channel steepness and chi using an adopted reference concavity of approximately 0.354.</li><li>Compared sinuosity over 5 km and 2.5 km reaches.</li><li>Identified 17 knickpoint candidates using a 30 m vertical tolerance.</li><li>Compared drainage metrics with geological mapping and swath profiles.</li></ul><h3>What the results showed</h3><p>The longest trunk extends approximately 66 km. Steepness, sinuosity, and knickpoint patterns vary across the network, supporting an interpretation that considers multiple geological and landscape controls. A knickpoint alone does not establish active tectonics.</p><p>The card image is a schematic illustration. Methods and results here are summarized from my September 2026 computational analysis report.</p>'},education:{tag:'AI MOVEMENT / SEPTEMBER 2022 — AUGUST 2024',title:'Making analytics approachable.',body:'<p>As a Data Analyst and Instructor at AI Movement, I developed and delivered practical training that helped learners build confidence with analytical tools.</p><h3>Topics and delivery</h3><ul><li>Excel for data analysis, Python, and SQL.</li><li>Hands-on exercises, projects, and real-world examples.</li><li>Training materials tailored to different experience levels.</li><li>Learner assessments to identify gaps and improve the training experience.</li><li>Collaboration with stakeholders to understand training needs.</li></ul><h3>Teaching philosophy</h3><p>Connect each technique to a question. Give learners space to practice, then help them explain the insight in their own words.</p><p>The code shown on the portfolio card is an illustrative teaching motif.</p>'}};
const dialog=document.querySelector('dialog');document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const project=work[button.dataset.project];document.querySelector('#dialog-tag').textContent=project.tag;document.querySelector('#dialog-title').textContent=project.title;document.querySelector('#dialog-body').innerHTML=project.body;dialog.showModal();document.body.classList.add('modal-open')}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));document.querySelector('#year').textContent=new Date().getFullYear();

document.querySelectorAll('[data-analytics-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-analytics-filter]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('.analytics-project').forEach(p=>p.hidden=button.dataset.analyticsFilter!=='all'&&p.dataset.analyticsCategory!==button.dataset.analyticsFilter)}));
